-- M-4e : 원본(출처) 메타데이터 선택 가져오기 (docs/source-import-m4e.md, 정책 docs/m4-foundation.md 5.5·5.10)
--  1) TB_TBL.SRC_ANTN_CN · TB_COL.SRC_ANTN_CN : 원본 COMMENT (출처 주석 내용). 업무 설명(TBL_EXPLN·COL_EXPLN)과 따로 둔다. 기존 행은 null 로 남는다
--  2) TB_SRC_IMPRT_EXCN : 가져오기 실행 이력 (기준 연결·적용한 수집 실행·반영 순서·모델 변경 그룹). 객체·속성별 변경 전후는 모델 변경 이력(TB_MDL_CHG_HSTRY, 출처 IMPORT)에 같은 변경 그룹으로 남는다
--     원본 쪽(SRC_CNTN_SN·SRC_CLCT_EXCN_SN)은 값만 둔다 (모듈·생명주기가 달라 FK 를 걸지 않는다 — 연결을 지워도 이력은 남는다)
--  3) 예제 (데이터 사전 단어·용어 → 물리 → 논리 → 매핑, 자체 인덱스) : 프로젝트 LEXORMA 의 예제가 있을 때만 넣는다
-- 증분 마이그레이션 : 이미 적용된 V0·V1·V2 는 고치지 않는다.

alter table TB_TBL add column SRC_ANTN_CN TEXT;
alter table TB_COL add column SRC_ANTN_CN TEXT;

create sequence SQ_SRC_IMPRT_EXCN start with 1 increment by 50;

-- 가져오기 실행 (성공한 가져오기만 남는다 : 실패하면 모델 변경과 함께 롤백된다). CHG_GROUP_ID = 요청 식별자 = 모델 변경 이력의 변경 그룹 (같은 요청을 두 번 적용하지 않는다)
create table TB_SRC_IMPRT_EXCN (
    SRC_IMPRT_EXCN_SN bigint not null,
    PRJ_SN bigint not null,
    SRC_CNTN_SN bigint not null,
    SRC_CLCT_EXCN_SN bigint,
    RFLT_ORD integer not null,
    CHG_GROUP_ID varchar(255) not null,
    IMPRT_CN TEXT,
    REG_DT timestamp(6),
    MDFCN_DT timestamp(6),
    RGTR_ID varchar(255),
    MDFR_ID varchar(255),
    constraint PK_SRC_IMPRT_EXCN primary key (SRC_IMPRT_EXCN_SN)
);

create unique index UX_SRC_IMPRT_EXCN_01 on TB_SRC_IMPRT_EXCN (CHG_GROUP_ID);
create index IX_SRC_IMPRT_EXCN_01 on TB_SRC_IMPRT_EXCN (PRJ_SN);

comment on column TB_TBL.SRC_ANTN_CN is '출처 주석 내용';
comment on column TB_COL.SRC_ANTN_CN is '출처 주석 내용';
comment on table TB_SRC_IMPRT_EXCN is '출처 가져오기 실행';
comment on column TB_SRC_IMPRT_EXCN.SRC_IMPRT_EXCN_SN is '출처 가져오기 실행 일련번호';
comment on column TB_SRC_IMPRT_EXCN.PRJ_SN is '프로젝트 일련번호';
comment on column TB_SRC_IMPRT_EXCN.SRC_CNTN_SN is '출처 접속 일련번호';
comment on column TB_SRC_IMPRT_EXCN.SRC_CLCT_EXCN_SN is '출처 수집 실행 일련번호';
comment on column TB_SRC_IMPRT_EXCN.RFLT_ORD is '반영 순서';
comment on column TB_SRC_IMPRT_EXCN.CHG_GROUP_ID is '변경 그룹 아이디';
comment on column TB_SRC_IMPRT_EXCN.IMPRT_CN is '가져오기 내용';
comment on column TB_SRC_IMPRT_EXCN.REG_DT is '등록 일시';
comment on column TB_SRC_IMPRT_EXCN.MDFCN_DT is '수정 일시';
comment on column TB_SRC_IMPRT_EXCN.RGTR_ID is '등록자 아이디';
comment on column TB_SRC_IMPRT_EXCN.MDFR_ID is '수정자 아이디';

-- ---------- 예제 : 데이터 사전 (새 단어 가져오기, 용어·용어 단어). 같은 이름이 이미 있으면 넣지 않는다 ----------
insert into TB_STD_WORD(STD_WORD_SN, PRJ_SN, ENCT_CYCL, WORD_NM, WORD_ENG_ABBR_NM, WORD_ENG_NM, WORD_EXPLN, FRMT_WORD_YN, DMN_CLSF_NM, ABBR_USE_YN, APRV_YN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_STD_WORD, 0, 1, '가져오기', 'IMPRT', 'Import', '원본 데이터베이스의 메타데이터를 모델로 들여오는 일.', false, null, true, true, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_PRJ p where p.PRJ_SN = 0 and not exists (select 1 from TB_STD_WORD where PRJ_SN = 0 and WORD_NM = '가져오기');
insert into TB_STD_TRM(STD_TRM_SN, PRJ_SN, ENCT_CYCL, TRM_NM, TRM_EXPLN, TRM_ENG_ABBR_NM, PBADMS_STD_CD_NM, JRSDC_INST_NM, STD_DMN_SN, APRV_YN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_STD_TRM, 0, 1, '출처_주석_내용', '원본 데이터베이스에서 가져온 COMMENT. 업무 설명과 따로 관리한다.', 'SRC_ANTN_CN', null, null, d.STD_DMN_SN, true, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_DMN d where d.PRJ_SN = 0 and d.DMN_NM = '내용T' and not exists (select 1 from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = '출처_주석_내용');
insert into TB_STD_TRM_WORD(STD_TRM_WORD_SN, STD_TRM_SN, STD_WORD_SN, SORT_ORD, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_STD_TRM_WORD, t.STD_TRM_SN, w.STD_WORD_SN, 1, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_TRM t join TB_STD_WORD w on w.PRJ_SN = 0 and w.WORD_NM = '출처' where t.PRJ_SN = 0 and t.TRM_NM = '출처_주석_내용' and not exists (select 1 from TB_STD_TRM_WORD x where x.STD_TRM_SN = t.STD_TRM_SN and x.SORT_ORD = 1);
insert into TB_STD_TRM_WORD(STD_TRM_WORD_SN, STD_TRM_SN, STD_WORD_SN, SORT_ORD, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_STD_TRM_WORD, t.STD_TRM_SN, w.STD_WORD_SN, 2, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_TRM t join TB_STD_WORD w on w.PRJ_SN = 0 and w.WORD_NM = '주석' where t.PRJ_SN = 0 and t.TRM_NM = '출처_주석_내용' and not exists (select 1 from TB_STD_TRM_WORD x where x.STD_TRM_SN = t.STD_TRM_SN and x.SORT_ORD = 2);
insert into TB_STD_TRM_WORD(STD_TRM_WORD_SN, STD_TRM_SN, STD_WORD_SN, SORT_ORD, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_STD_TRM_WORD, t.STD_TRM_SN, w.STD_WORD_SN, 3, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_TRM t join TB_STD_WORD w on w.PRJ_SN = 0 and w.WORD_NM = '내용' where t.PRJ_SN = 0 and t.TRM_NM = '출처_주석_내용' and not exists (select 1 from TB_STD_TRM_WORD x where x.STD_TRM_SN = t.STD_TRM_SN and x.SORT_ORD = 3);
insert into TB_STD_TRM(STD_TRM_SN, PRJ_SN, ENCT_CYCL, TRM_NM, TRM_EXPLN, TRM_ENG_ABBR_NM, PBADMS_STD_CD_NM, JRSDC_INST_NM, STD_DMN_SN, APRV_YN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_STD_TRM, 0, 1, '출처_가져오기_실행_일련번호', '출처 가져오기 실행 일련번호.', 'SRC_IMPRT_EXCN_SN', null, null, d.STD_DMN_SN, true, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_DMN d where d.PRJ_SN = 0 and d.DMN_NM = '일련번호L' and not exists (select 1 from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = '출처_가져오기_실행_일련번호');
insert into TB_STD_TRM_WORD(STD_TRM_WORD_SN, STD_TRM_SN, STD_WORD_SN, SORT_ORD, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_STD_TRM_WORD, t.STD_TRM_SN, w.STD_WORD_SN, 1, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_TRM t join TB_STD_WORD w on w.PRJ_SN = 0 and w.WORD_NM = '출처' where t.PRJ_SN = 0 and t.TRM_NM = '출처_가져오기_실행_일련번호' and not exists (select 1 from TB_STD_TRM_WORD x where x.STD_TRM_SN = t.STD_TRM_SN and x.SORT_ORD = 1);
insert into TB_STD_TRM_WORD(STD_TRM_WORD_SN, STD_TRM_SN, STD_WORD_SN, SORT_ORD, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_STD_TRM_WORD, t.STD_TRM_SN, w.STD_WORD_SN, 2, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_TRM t join TB_STD_WORD w on w.PRJ_SN = 0 and w.WORD_NM = '가져오기' where t.PRJ_SN = 0 and t.TRM_NM = '출처_가져오기_실행_일련번호' and not exists (select 1 from TB_STD_TRM_WORD x where x.STD_TRM_SN = t.STD_TRM_SN and x.SORT_ORD = 2);
insert into TB_STD_TRM_WORD(STD_TRM_WORD_SN, STD_TRM_SN, STD_WORD_SN, SORT_ORD, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_STD_TRM_WORD, t.STD_TRM_SN, w.STD_WORD_SN, 3, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_TRM t join TB_STD_WORD w on w.PRJ_SN = 0 and w.WORD_NM = '실행' where t.PRJ_SN = 0 and t.TRM_NM = '출처_가져오기_실행_일련번호' and not exists (select 1 from TB_STD_TRM_WORD x where x.STD_TRM_SN = t.STD_TRM_SN and x.SORT_ORD = 3);
insert into TB_STD_TRM_WORD(STD_TRM_WORD_SN, STD_TRM_SN, STD_WORD_SN, SORT_ORD, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_STD_TRM_WORD, t.STD_TRM_SN, w.STD_WORD_SN, 4, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_TRM t join TB_STD_WORD w on w.PRJ_SN = 0 and w.WORD_NM = '일련번호' where t.PRJ_SN = 0 and t.TRM_NM = '출처_가져오기_실행_일련번호' and not exists (select 1 from TB_STD_TRM_WORD x where x.STD_TRM_SN = t.STD_TRM_SN and x.SORT_ORD = 4);
insert into TB_STD_TRM(STD_TRM_SN, PRJ_SN, ENCT_CYCL, TRM_NM, TRM_EXPLN, TRM_ENG_ABBR_NM, PBADMS_STD_CD_NM, JRSDC_INST_NM, STD_DMN_SN, APRV_YN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_STD_TRM, 0, 1, '가져오기_내용', '가져오기 실행의 요약 (적용 항목 수, 대상 테이블).', 'IMPRT_CN', null, null, d.STD_DMN_SN, true, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_DMN d where d.PRJ_SN = 0 and d.DMN_NM = '내용T' and not exists (select 1 from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = '가져오기_내용');
insert into TB_STD_TRM_WORD(STD_TRM_WORD_SN, STD_TRM_SN, STD_WORD_SN, SORT_ORD, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_STD_TRM_WORD, t.STD_TRM_SN, w.STD_WORD_SN, 1, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_TRM t join TB_STD_WORD w on w.PRJ_SN = 0 and w.WORD_NM = '가져오기' where t.PRJ_SN = 0 and t.TRM_NM = '가져오기_내용' and not exists (select 1 from TB_STD_TRM_WORD x where x.STD_TRM_SN = t.STD_TRM_SN and x.SORT_ORD = 1);
insert into TB_STD_TRM_WORD(STD_TRM_WORD_SN, STD_TRM_SN, STD_WORD_SN, SORT_ORD, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_STD_TRM_WORD, t.STD_TRM_SN, w.STD_WORD_SN, 2, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_TRM t join TB_STD_WORD w on w.PRJ_SN = 0 and w.WORD_NM = '내용' where t.PRJ_SN = 0 and t.TRM_NM = '가져오기_내용' and not exists (select 1 from TB_STD_TRM_WORD x where x.STD_TRM_SN = t.STD_TRM_SN and x.SORT_ORD = 2);

-- ---------- 예제 : 물리 모델. 테이블 TB_SRC_IMPRT_EXCN, 컬럼 TB_TBL·TB_COL 의 SRC_ANTN_CN (같은 이름이 이미 있으면 넣지 않는다) ----------
insert into TB_TBL(TBL_SN, PRJ_SN, SCHM_SN, TBL_NM, TBL_KORN_NM, TBL_EXPLN, MSTR_TBL_YN, SORT_ORD, APRV_YN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_TBL, 0, s.SCHM_SN, 'TB_SRC_IMPRT_EXCN', '출처 가져오기 실행', 'Lexorma 원본 메타데이터 가져오기 실행 이력', false, (select coalesce(max(SORT_ORD), 0) + 1 from TB_TBL where PRJ_SN = 0), true, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_SCHM s where s.PRJ_SN = 0 and s.BSC_YN = true and not exists (select 1 from TB_TBL where PRJ_SN = 0 and TBL_NM = 'TB_SRC_IMPRT_EXCN');
insert into TB_COL(COL_SN, PRJ_SN, TBL_SN, TBL_NM, COL_NM, COL_EXPLN, DATA_TYPE_NM, MAX_LEN, DATA_PRCSN, DCPT_LEN, NULL_ALWNC_YN, BSC_VL, SORT_ORD, MSTR_DATA_YN, RFRNC_TBL_NM, ESNTL_YN, SNSTV_INFO_YN, PK_YN, UNQ_YN, IDX_YN, ENCPT_YN, APRV_YN, STD_TRM_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_COL, 0, t.TBL_SN, 'TB_SRC_IMPRT_EXCN', 'SRC_IMPRT_EXCN_SN', '출처 가져오기 실행 일련번호', 'BIGINT', null, null, null, false, null, 1, false, null, true, false, true, false, false, false, true, (select STD_TRM_SN from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = '출처_가져오기_실행_일련번호'), current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_TBL t where t.PRJ_SN = 0 and t.TBL_NM = 'TB_SRC_IMPRT_EXCN' and not exists (select 1 from TB_COL c where c.TBL_SN = t.TBL_SN and c.COL_NM = 'SRC_IMPRT_EXCN_SN');
insert into TB_COL(COL_SN, PRJ_SN, TBL_SN, TBL_NM, COL_NM, COL_EXPLN, DATA_TYPE_NM, MAX_LEN, DATA_PRCSN, DCPT_LEN, NULL_ALWNC_YN, BSC_VL, SORT_ORD, MSTR_DATA_YN, RFRNC_TBL_NM, ESNTL_YN, SNSTV_INFO_YN, PK_YN, UNQ_YN, IDX_YN, ENCPT_YN, APRV_YN, STD_TRM_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_COL, 0, t.TBL_SN, 'TB_SRC_IMPRT_EXCN', 'PRJ_SN', '프로젝트 일련번호', 'BIGINT', null, null, null, false, null, 2, false, null, true, false, false, false, false, false, true, (select STD_TRM_SN from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = '프로젝트_일련번호'), current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_TBL t where t.PRJ_SN = 0 and t.TBL_NM = 'TB_SRC_IMPRT_EXCN' and not exists (select 1 from TB_COL c where c.TBL_SN = t.TBL_SN and c.COL_NM = 'PRJ_SN');
