insert into TB_COL(COL_SN, PRJ_SN, TBL_SN, TBL_NM, COL_NM, COL_EXPLN, DATA_TYPE_NM, MAX_LEN, DATA_PRCSN, DCPT_LEN, NULL_ALWNC_YN, BSC_VL, SORT_ORD, MSTR_DATA_YN, RFRNC_TBL_NM, ESNTL_YN, SNSTV_INFO_YN, PK_YN, UNQ_YN, IDX_YN, ENCPT_YN, APRV_YN, STD_TRM_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_COL, 0, t.TBL_SN, 'TB_SRC_IMPRT_EXCN', 'SRC_CLCT_EXCN_SN', '출처 수집 실행 일련번호', 'BIGINT', null, null, null, true, null, 4, false, null, false, false, false, false, false, false, true, (select STD_TRM_SN from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = '출처_수집_실행_일련번호'), current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_TBL t where t.PRJ_SN = 0 and t.TBL_NM = 'TB_SRC_IMPRT_EXCN' and not exists (select 1 from TB_COL c where c.TBL_SN = t.TBL_SN and c.COL_NM = 'SRC_CLCT_EXCN_SN');
insert into TB_COL(COL_SN, PRJ_SN, TBL_SN, TBL_NM, COL_NM, COL_EXPLN, DATA_TYPE_NM, MAX_LEN, DATA_PRCSN, DCPT_LEN, NULL_ALWNC_YN, BSC_VL, SORT_ORD, MSTR_DATA_YN, RFRNC_TBL_NM, ESNTL_YN, SNSTV_INFO_YN, PK_YN, UNQ_YN, IDX_YN, ENCPT_YN, APRV_YN, STD_TRM_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_COL, 0, t.TBL_SN, 'TB_SRC_IMPRT_EXCN', 'RFLT_ORD', '반영 순서', 'INTEGER', null, null, null, false, null, 5, false, null, true, false, false, false, false, false, true, (select STD_TRM_SN from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = '반영_순서'), current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_TBL t where t.PRJ_SN = 0 and t.TBL_NM = 'TB_SRC_IMPRT_EXCN' and not exists (select 1 from TB_COL c where c.TBL_SN = t.TBL_SN and c.COL_NM = 'RFLT_ORD');
