insert into TB_LGCL_IDNTFR(LGCL_IDNTFR_SN, LGCL_ENTT_SN, IDNTFR_NM, BSC_YN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_LGCL_IDNTFR, e.LGCL_ENTT_SN, '출처 가져오기 실행 식별자', true, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_LGCL_ENTT e where e.LGCL_MDL_SN = (select LGCL_MDL_SN from TB_LGCL_MDL where PRJ_SN = 0 and MDL_NM = 'LEXORMA') and e.ENTT_NM = '출처 가져오기 실행' and not exists (select 1 from TB_LGCL_IDNTFR i where i.LGCL_ENTT_SN = e.LGCL_ENTT_SN and i.BSC_YN = true);
insert into TB_LGCL_IDNTFR_ATRB(LGCL_IDNTFR_ATRB_SN, LGCL_IDNTFR_SN, LGCL_ATRB_SN, SORT_ORD) select next value for SQ_LGCL_IDNTFR_ATRB, i.LGCL_IDNTFR_SN, a.LGCL_ATRB_SN, 1 from TB_LGCL_IDNTFR i join TB_LGCL_ATRB a on a.LGCL_ENTT_SN = i.LGCL_ENTT_SN and a.ATRB_NM = '출처 가져오기 실행 일련번호' where i.LGCL_ENTT_SN = (select LGCL_ENTT_SN from TB_LGCL_ENTT where LGCL_MDL_SN = (select LGCL_MDL_SN from TB_LGCL_MDL where PRJ_SN = 0 and MDL_NM = 'LEXORMA') and ENTT_NM = '출처 가져오기 실행') and i.IDNTFR_NM = '출처 가져오기 실행 식별자' and not exists (select 1 from TB_LGCL_IDNTFR_ATRB x where x.LGCL_IDNTFR_SN = i.LGCL_IDNTFR_SN);
insert into TB_LGCL_ATRB(LGCL_ATRB_SN, LGCL_ENTT_SN, ATRB_NM, ATRB_EXPLN, DATA_TYPE_NM, ESNTL_YN, SORT_ORD, STD_TRM_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_LGCL_ATRB, e.LGCL_ENTT_SN, '출처 주석 내용', null, null, false, (select coalesce(max(a2.SORT_ORD), 0) + 1 from TB_LGCL_ATRB a2 where a2.LGCL_ENTT_SN = e.LGCL_ENTT_SN), (select STD_TRM_SN from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = '출처_주석_내용'), current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_LGCL_ENTT e where e.LGCL_MDL_SN = (select LGCL_MDL_SN from TB_LGCL_MDL where PRJ_SN = 0 and MDL_NM = 'LEXORMA') and e.ENTT_NM = '테이블' and not exists (select 1 from TB_LGCL_ATRB a where a.LGCL_ENTT_SN = e.LGCL_ENTT_SN and a.ATRB_NM = '출처 주석 내용');
insert into TB_LGCL_ATRB(LGCL_ATRB_SN, LGCL_ENTT_SN, ATRB_NM, ATRB_EXPLN, DATA_TYPE_NM, ESNTL_YN, SORT_ORD, STD_TRM_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_LGCL_ATRB, e.LGCL_ENTT_SN, '출처 주석 내용', null, null, false, (select coalesce(max(a2.SORT_ORD), 0) + 1 from TB_LGCL_ATRB a2 where a2.LGCL_ENTT_SN = e.LGCL_ENTT_SN), (select STD_TRM_SN from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = '출처_주석_내용'), current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_LGCL_ENTT e where e.LGCL_MDL_SN = (select LGCL_MDL_SN from TB_LGCL_MDL where PRJ_SN = 0 and MDL_NM = 'LEXORMA') and e.ENTT_NM = '컬럼' and not exists (select 1 from TB_LGCL_ATRB a where a.LGCL_ENTT_SN = e.LGCL_ENTT_SN and a.ATRB_NM = '출처 주석 내용');

-- ---------- 예제 : 논리 ↔ 물리 매핑 (V2 와 같은 규칙 : 새 엔터티·속성만 이어진다) ----------
insert into TB_ENTT_TBL_MPNG(ENTT_TBL_MPNG_SN, PRJ_SN, LGCL_ENTT_SN, TBL_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID)
select next value for SQ_ENTT_TBL_MPNG, 0, e.LGCL_ENTT_SN, t.TBL_SN, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM'
from TB_LGCL_ENTT e
join TB_LGCL_MDL m on m.LGCL_MDL_SN = e.LGCL_MDL_SN and m.PRJ_SN = 0 and m.MDL_NM = 'LEXORMA'
join TB_TBL t on t.PRJ_SN = 0 and t.TBL_KORN_NM = e.ENTT_NM
where e.PRJ_SN = 0
  and (select count(*) from TB_TBL t2 where t2.PRJ_SN = 0 and t2.TBL_KORN_NM = e.ENTT_NM) = 1
  and not exists (select 1 from TB_ENTT_TBL_MPNG x where x.LGCL_ENTT_SN = e.LGCL_ENTT_SN)
  and not exists (select 1 from TB_ENTT_TBL_MPNG x where x.TBL_SN = t.TBL_SN);
insert into TB_ATRB_COL_MPNG(ATRB_COL_MPNG_SN, ENTT_TBL_MPNG_SN, LGCL_ATRB_SN, COL_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID)
select next value for SQ_ATRB_COL_MPNG, mp.ENTT_TBL_MPNG_SN, a.LGCL_ATRB_SN, c.COL_SN, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM'
from TB_ENTT_TBL_MPNG mp
join TB_LGCL_ENTT e on e.LGCL_ENTT_SN = mp.LGCL_ENTT_SN
join TB_LGCL_MDL m on m.LGCL_MDL_SN = e.LGCL_MDL_SN and m.PRJ_SN = 0 and m.MDL_NM = 'LEXORMA'
join TB_TBL t on t.TBL_SN = mp.TBL_SN and t.TBL_KORN_NM = e.ENTT_NM
join TB_LGCL_ATRB a on a.LGCL_ENTT_SN = e.LGCL_ENTT_SN
join TB_COL c on c.TBL_SN = t.TBL_SN and c.STD_TRM_SN = a.STD_TRM_SN
where mp.PRJ_SN = 0
  and (select count(*) from TB_LGCL_ATRB a2 where a2.LGCL_ENTT_SN = e.LGCL_ENTT_SN and a2.STD_TRM_SN = a.STD_TRM_SN) = 1
  and (select count(*) from TB_COL c2 where c2.TBL_SN = t.TBL_SN and c2.STD_TRM_SN = a.STD_TRM_SN) = 1
  and not exists (select 1 from TB_ATRB_COL_MPNG x where x.LGCL_ATRB_SN = a.LGCL_ATRB_SN)
  and not exists (select 1 from TB_ATRB_COL_MPNG x where x.COL_SN = c.COL_SN);

-- ---------- 예제 : 이 파일의 create index 를 예제 인덱스로 (V2 와 같은 규칙 : 출처 USER·승인·등록자 SYSTEM, 같은 이름이 있거나 컬럼이 없으면 건너뛴다) ----------
create table TMP_IDX_SEED (TBL_NM varchar(255) not null, IDX_NM varchar(255) not null, UNQ_YN boolean not null, COL_NM varchar(255) not null, COL_ORD integer not null);
insert into TMP_IDX_SEED(TBL_NM, IDX_NM, UNQ_YN, COL_NM, COL_ORD) values
('TB_SRC_IMPRT_EXCN', 'UX_SRC_IMPRT_EXCN_01', true, 'CHG_GROUP_ID', 1),
('TB_SRC_IMPRT_EXCN', 'IX_SRC_IMPRT_EXCN_01', false, 'PRJ_SN', 1);
insert into TB_TBL_IDX(IDX_SN, PRJ_SN, TBL_SN, IDX_NM, IDX_TYPE_NM, UNQ_YN, APRV_YN, IDX_SRC_CD, DRVN_COL_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID)
select next value for SQ_TBL_IDX, 0, t.TBL_SN, s.IDX_NM, null, s.UNQ_YN, true, 'USER', null, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM'
from (select distinct TBL_NM, IDX_NM, UNQ_YN from TMP_IDX_SEED) s
join TB_TBL t on t.PRJ_SN = 0 and t.TBL_NM = s.TBL_NM
where not exists (select 1 from TB_TBL_IDX i where i.TBL_SN = t.TBL_SN and i.IDX_NM = s.IDX_NM)
  and (select count(*) from TMP_IDX_SEED x join TB_COL c on c.TBL_SN = t.TBL_SN and c.COL_NM = x.COL_NM where x.IDX_NM = s.IDX_NM)
    = (select count(*) from TMP_IDX_SEED x where x.IDX_NM = s.IDX_NM);
insert into TB_TBL_IDX_COL(IDX_COL_SN, IDX_SN, COL_SN, COL_ORD)
select next value for SQ_TBL_IDX_COL, i.IDX_SN, c.COL_SN, s.COL_ORD
from TMP_IDX_SEED s
join TB_TBL t on t.PRJ_SN = 0 and t.TBL_NM = s.TBL_NM
join TB_TBL_IDX i on i.TBL_SN = t.TBL_SN and i.IDX_NM = s.IDX_NM
join TB_COL c on c.TBL_SN = t.TBL_SN and c.COL_NM = s.COL_NM
where not exists (select 1 from TB_TBL_IDX_COL x where x.IDX_SN = i.IDX_SN);
drop table TMP_IDX_SEED;
